// Java types for the Helios Bootstrap API, generated by Smithy Java's type
// code generation from the Smithy model in ../../contract (helios-contract,
// pinned by the git submodule). Request and response types, errors and their
// schemas; the routing and the API Gateway glue are written by hand.

plugins {
    `java-library`
    alias(libs.plugins.smithy.base)
}

dependencies {
    smithyBuild(libs.smithy.java.codegen)
    // The model's traits: restJson1, protocol tests and ValidationException.
    implementation(libs.smithy.aws.traits)
    implementation(libs.smithy.protocol.test.traits)
    implementation(libs.smithy.validation.model)

    api(libs.smithy.java.core)
    api(libs.smithy.java.json)
    api(libs.smithy.java.framework.errors)

    // ContractBodiesTest reads the protocol tests from the model.
    testImplementation(libs.smithy.protocol.test.traits)
}

tasks.test {
    systemProperty("helios.contract.model", file("../../contract/model").absolutePath)
}

smithy {
    // The model lives in the contract submodule; don't let `smithy format`
    // rewrite it.
    format = false
}

afterEvaluate {
    val generated = smithy.getPluginProjectionPath(smithy.sourceProjection.get(), "java-codegen").get()
    sourceSets {
        main {
            java {
                srcDir("$generated/java")
            }
            resources {
                srcDir("$generated/resources")
            }
        }
    }
}

tasks.processResources { dependsOn(tasks.named("smithyBuild")) }

tasks.compileJava {
    dependsOn(tasks.named("smithyBuild"))
    // Generated code isn't held to our lint settings.
    options.compilerArgs.removeAll { it.startsWith("-Xlint") }
}

// Checkstyle and Spotless check only hand-written code (src/), and coverage
// only counts hand-written classes: everything here is generated.
tasks.named<Checkstyle>("checkstyleMain") { enabled = false }
tasks.named<JacocoCoverageVerification>("jacocoCoverage") { enabled = false }
